CREATE POLICY "Users upload own community media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'post-media' AND (storage.foldername(name))[1] = (auth.uid())::text AND (storage.foldername(name))[2] = 'community'); CREATE POLICY "Users delete own community media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'post-media' AND (storage.foldername(name))[1] = (auth.uid())::text AND (storage.foldername(name))[2] = 'community');